<template>
  <section class="stage-experience" aria-label="交通与两侧日程联动">
    <nav class="phase-switch" aria-label="查看交通阶段"><button v-for="(p,i) in phases" :key="p" :aria-pressed="phase===i" :class="{active:phase===i}" @click="phase=i"><span>0{{i+1}}</span>{{p}}</button></nav>
    <Transition name="phase" mode="out-in">
      <div :key="phase+'-'+edge.from+'-'+edge.to" class="phase-content">
        <template v-if="phase===1">
          <div class="boarding-pass"><div class="pass-top"><span>{{edge.date}} · {{leg?.mode==='flight'?'飞行':'城际交通'}}</span><strong>{{leg?.service_number || '寻找合适的一班'}}</strong><span>{{leg?.booking_status==='booked'?'已订':'计划中'}}</span></div><div class="pass-route"><div><strong>{{time(leg?.departure_time)}}</strong><span>{{leg?.departure_station || edge.fromName}}</span></div><div class="pass-line"><span>{{leg?'在途中':'连接两座城市'}}</span><i></i><small>{{leg?.seat_class || '席别待确认'}}</small></div><div><strong>{{time(leg?.arrival_time)}}</strong><span>{{leg?.arrival_station || edge.toName}}</span></div></div><div class="pass-bottom"><span>{{edge.fromName}} <b>↗</b> {{edge.toName}}</span><span>全体票价 {{leg?.ticket_total == null?'待确认':'¥'+leg.ticket_total}}</span></div></div>
          <p class="phase-caption">一段交通，也会改变两座城市的一天。切换两侧，查看出发前与抵达后的安排。</p>
        </template>
        <template v-else>
          <div class="stage-city"><span class="stage-icon">{{phase===0?'↗':'↘'}}</span><div><small>{{phase===0?'离开之前':'到达之后'}} · {{edge.date}}</small><h3>{{phase===0?edge.fromName:edge.toName}}</h3></div><div class="stage-window"><small>已保存安排</small><strong>{{context?.period || (phase===0?'从出发地启程':'回到目的地')}}</strong></div></div>
          <div v-if="context?.window && leg" class="stage-deadline"><strong>{{phase===0?clock(context.window.end_minutes)+' 前结束市内安排':clock(context.window.start_minutes)+' 后可开始市内安排'}}</strong><p>按当前班次与已保存的接驳、行李及办理预留计算，接驳仍为估计。</p></div>
          <ol v-if="context?.items?.length" class="stage-events"><li v-for="(item,i) in context.items" :key="i"><time>{{item.start_time}}</time><span>{{item.ref_name || item.description || '行程安排'}}</span><small>{{item.end_time}}</small></li></ol>
          <p v-else class="phase-caption">这一侧未安排游览与用餐。<template v-if="context?.hotel">酒店位置参考：{{context.hotel}}。</template>请留出退房、行李及途中用餐时间。</p>
          <button v-if="context && !readonly" class="stage-edit" :disabled="disabled||editingDisabled" @click="$emit('edit',context.id)">调整 {{context.city}} 当天安排 →</button>
        </template>
      </div>
    </Transition>
    <div v-if="leg && !readonly" class="buffer-controls"><div><strong>给衔接留出余量</strong><p>调整预留，再预览两侧日程是否放得下。</p></div><div v-for="b in buffers" :key="b.key" class="buffer-control"><span>{{b.label}}</span><div><button :aria-label="b.label+'减少15分钟'" :disabled="disabled || Number(leg[b.key]||0)<15" @click="change(b.key,-15)">−</button><output>{{leg[b.key]??0}}<small> 分钟</small></output><button :aria-label="b.label+'增加15分钟'" :disabled="disabled || Number(leg[b.key]||0)>=720" @click="change(b.key,15)">＋</button></div></div></div>
  </section>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
const props=defineProps<{edge:any;leg:any;days:any[];disabled:boolean;readonly?:boolean;editingDisabled?:boolean}>()
const emit=defineEmits<{(e:'edit',id:string):void;(e:'buffer',value:{key:string;value:number}):void}>()
const phase=ref(1),phases=['出发前','在途中','抵达后']
const context=computed(()=>props.days.find(d=>d.id===(phase.value===0?props.edge.from:props.edge.to)))
const time=(v?:string)=>v?.slice(11,16)||'—:—'
const clock=(n:number)=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')
const buffers=[{key:'transfer_before_minutes',label:'去车站接驳'},{key:'station_buffer_minutes',label:'候车与安检'},{key:'transfer_after_minutes',label:'抵达后接驳'}]
function change(key:string,delta:number){emit('buffer',{key,value:Math.max(0,Math.min(720,Number(props.leg[key]||0)+delta))})}
watch(()=>props.edge.from+'-'+props.edge.to,()=>{phase.value=1})
</script>
<style scoped>
.stage-experience{border:1px solid var(--trip-line);background:linear-gradient(135deg,#ffffff08,transparent);border-radius:22px;padding:22px;margin:24px 0;color:var(--trip-text)}.phase-switch{display:flex;width:max-content;max-width:100%;margin:0 auto 24px;padding:5px;border:1px solid var(--trip-line);background:var(--trip-bg);border-radius:100px}.phase-switch button{font:inherit;font-size:12px;border:0;background:transparent;color:var(--trip-muted);padding:12px 20px;border-radius:100px;cursor:pointer;transition:color .25s,background .25s}.phase-switch button span{margin-right:8px;opacity:.6;font-size:10px}.phase-switch .active{background:var(--trip-accent);color:var(--trip-on-accent)}.phase-content{min-height:240px;max-width:850px;margin:auto}.boarding-pass{border:1px solid var(--trip-line);background:var(--trip-surface);border-radius:18px;overflow:hidden;box-shadow:0 20px 50px #00000012}.pass-top,.pass-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 24px;font-size:11px;color:var(--trip-muted)}.pass-top strong{font-size:18px;color:var(--trip-text);letter-spacing:.05em}.pass-route{display:grid;grid-template-columns:1fr 1fr 1fr;gap:25px;align-items:center;padding:14px 30px 26px}.pass-route>div{display:flex;flex-direction:column;gap:6px}.pass-route>div:last-child{text-align:right}.pass-route strong{font-size:42px;font-weight:450;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.pass-route span{font-size:13px}.pass-line{text-align:center;color:var(--trip-muted)}.pass-line span,.pass-line small{font-size:10px}.pass-line i{position:relative;border-top:1px solid var(--trip-accent);margin:14px 0}.pass-line i::after{content:'→';position:absolute;right:0;top:-14px;color:var(--trip-accent)}.pass-bottom{border-top:1px dashed var(--trip-line);background:#ffffff03}.pass-bottom b{margin:0 16px;color:var(--trip-accent)}.phase-caption{text-align:center;font-size:12px;color:var(--trip-muted);line-height:1.8;margin:20px 0 4px}.stage-city{display:flex;align-items:center;gap:18px;margin-bottom:20px}.stage-icon{font-size:34px;color:var(--trip-accent)}.stage-city small{font-size:11px;color:var(--trip-muted)}.stage-city h3{font-size:30px!important;margin:4px 0!important;font-weight:500!important}.stage-window{margin-left:auto;text-align:right;display:flex;flex-direction:column;gap:8px}.stage-window strong{font-size:15px}.stage-events{list-style:none;margin:0;padding:0;max-height:255px;overflow:auto;scrollbar-width:thin}.stage-events li{display:flex;gap:18px;padding:12px;border-bottom:1px solid var(--trip-line);font-size:12px}.stage-events time{color:var(--trip-accent);font-variant-numeric:tabular-nums}.stage-events small{margin-left:auto;color:var(--trip-muted);flex-shrink:0}.stage-edit{margin-top:15px!important}.buffer-controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-top:25px;padding-top:24px;border-top:1px solid var(--trip-line)}.buffer-controls>div{flex:1;min-width:180px}.buffer-controls strong{font-size:13px}.buffer-controls p{font-size:11px;color:var(--trip-muted);margin:5px 0}.buffer-controls .buffer-control{display:flex;flex-direction:column;gap:8px;font-size:11px;color:var(--trip-muted)}.buffer-controls .buffer-control>div{display:flex;align-items:center;border:1px solid var(--trip-line);border-radius:10px;overflow:hidden}.buffer-controls button{border:0!important;margin:0!important;background:transparent!important;color:var(--trip-accent);padding:8px 10px!important;font-size:14px;cursor:pointer}.buffer-controls output{font-size:14px;min-width:62px;text-align:center;color:var(--trip-text)}.buffer-controls output small{font-size:9px;color:var(--trip-muted)}button:disabled{opacity:.4;cursor:not-allowed}button:focus-visible{outline:2px solid var(--trip-accent);outline-offset:3px}.phase-enter-active{transition:opacity .25s,transform .35s cubic-bezier(.22,1,.36,1)}.phase-leave-active{transition:opacity .12s}.phase-enter-from{opacity:0;transform:translateY(8px)}.phase-leave-to{opacity:0}
@media(max-width:600px){.stage-experience{padding:16px}.phase-switch button{padding:10px 13px}.phase-switch button span{display:none}.pass-route{padding:14px 16px 22px;gap:12px}.pass-route strong{font-size:30px}.pass-route span{font-size:11px}.pass-top,.pass-bottom{padding:14px;font-size:10px}.buffer-controls{gap:16px 10px}.buffer-controls>div{flex-basis:100%}.buffer-controls .buffer-control{flex:1;min-width:120px}.buffer-controls .buffer-control>div{justify-content:space-between}.stage-window strong{font-size:12px}.stage-city{gap:10px}.stage-events li{gap:10px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}.phase-enter-from{transform:none}}
</style>

<style scoped>.stage-deadline{padding:16px 20px;margin-bottom:18px;border:1px solid var(--trip-line);border-radius:12px;background:var(--trip-soft)}.stage-deadline strong{color:var(--trip-accent);font-size:16px}.stage-deadline p{font-size:11px;color:var(--trip-muted);line-height:1.8;margin-bottom:0}</style>
